import React from 'react';
import './BikeList.css';

function BikeList() {
  const bikes = [];

  return (
    <div className="bike-list">
      <h2>Available Bikes</h2>
      <ul>
        {bikes.map((bike, index) => (
          <li key={index}>{bike}</li>
        ))}
      </ul>
    </div>
  );
}

export default BikeList;
